        return acc + { [text.lower(c.domain)]: c.name }
    } else {
        return acc
    }
    return next
}
results = for ct in contacts {
    has_phone = ct.phone != null and ct.phone != ""
    valid = regex.test(ct.phone, "^[+]1[0-9]{10}$") if has_phone else false
    digits_raw = regex.replace(ct.phone, "[^0-9]", "") if has_phone else ""
    digits = text.slice(digits_raw, 1) if text.length(digits_raw) == 11 and text.starts_with(digits_raw, "1") else digits_raw
    new_phone = "+1" + digits if has_phone and not valid and text.length(digits) == 10 else null
    comp_empty = if ct.company == null {
        return true
    } else {
        return text.trim(ct.company) == ""
    }
    parts = text.split(ct.email, "@") if ct.email != null else []
    domain = text.lower(parts[1]) if list.length(parts) == 2 else ""
    new_company = by_domain[domain] if comp_empty and domain != "" and domain in by_domain else null
    can_update = ct.id != null
    phone_changed = new_phone != null and can_update
    company_filled = new_company != null and can_update
    upd = if phone_changed or company_filled {
        u = boundary retry 3 {
            return update_contact({ id: ct.id, phone: new_phone, company: new_company })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
        return u
    } else {
        return null
    }
    return { phone_changed, company_filled }
}
phones_fixed = fold acc = 0 for r in results {
    next = if r.phone_changed {
        return acc + 1
    } else {
        return acc
    }
    return next
}
companies_filled = fold acc = 0 for r in results {
    next = if r.company_filled {
        return acc + 1
    } else {
        return acc
    }
    return next
}
sub = submit_result({ answer: { phones_fixed, companies_filled } })
return { phones_fixed, companies_filled, recorded: sub.recorded }

